INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 2, 0, "お！\nあそこに困ってそうな人発見！", 1, 1, 0, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 1, 1001, 1.4, "春咲 ひより", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "わ、わたし、\nなに言ってるんだろ\nあはは…", 2, 0, "大切な人を\n守れるようになりたい…って", 1, 1, 0, "みんなみたいに\nわたしも強くならなきゃ", 1, 1002, 1.4, "草野 優衣", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "少しは磨かれると思いますよ。", 2, 0, "キミに必要な集中力と感性が", 1, 1, 0, "フェンシングを始めてみては？", 1, 1003, 1.4, "士条 怜", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "みそぎはねぇ、\nかくれんぼやりたい！", 2, 0, "今日はなにして遊ぶ？", 1, 1, 0, "ねぇ、にいちゃん！", 1, 1004, 1.5, "穂高 みそぎ", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "私といっしょに…\nいかない？", 2, 0, "ねぇ…", 1, 1, 0, "風宮あかりです", 1, 1006, 1.4, "風宮 あかり", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "食べ物の恨みは怖いのー", 2, 0, "プリンたべたいのー", 1, 1, 0, "出雲宮子なのー", 1, 1007, 1.5, "出雲 宮子", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "いいよ。\n見られることは運命さ…", 2, 0, "キミもボクの美貌に\n吸い寄せられたんだね。", 1, 1, 0, "ボクは虹村雪。", 1, 1008, 1.4, "虹村 雪", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "人呼んで「疾風の冥姫」!!", 2, 0, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 1, 1, 0, "フッ…聞いて後悔するがいい！", 1, 1009, 1.4, "柊杏奈", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "ほんまおおきにやわ～♪", 2, 0, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 1, 1, 0, "マホマホ王国のプリンセス、\nまほ姫どす", 1, 1010, 1.5, "姫宮 真歩", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "ここで会ったが\n100年目～！", 2, 0, "生き別れたお兄ちゃんを探して\n三千世界！", 1, 1, 0, "衣之咲璃乃です！", 1, 1011, 1.4, "衣之咲 璃乃", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "…って、お願い！\n誰にも言わないでおいて～！", 2, 0, "ち、超能力って…\n何のことかな～？", 1, 1, 0, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 1, 1012, 1.4, "柏崎 初音", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 2, 0, "一応カリスマ読モJKやってまっす！", 1, 1, 0, "ちょす！\n美波鈴奈だよ～♪", 1, 1016, 1.4, "美波 鈴奈", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "でも、沖縄もとってもいいとこさー", 2, 0, "東京は遊園地みたいなところさー", 1, 1, 0, "はいたーい。\n喜屋武香織さー。", 1, 1017, 1.4, "喜屋武 香織", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "イオちゃんって呼んでね。", 2, 0, "先生って呼ばれるのは\nくすぐったいから", 1, 1, 0, "支倉伊緒です。", 1, 1018, 1.4, "支倉 伊緒", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "ミミをおいてかないでぇ～", 2, 0, "あ！/\お兄ちゃ～ん\nまってよ～", 1, 1, 0, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 1, 1020, 1.5, "茜 ミミ", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "ふぇぇぇぇぇん……", 2, 0, "あの……\nふぇ……", 1, 1, 0, "あ…あの…えっと…\n栗…林…くるみ…です……", 1, 1021, 1.5, "栗林 くるみ", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "なんてありがとうございます！", 2, 0, "こんな私に貴重な時間を\n割いていただき、", 1, 1, 0, "風宮よりです。\nあああああ！", 1, 1022, 1.4, "風宮 より", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "私こっち行きたいー\nね、早く早くー", 2, 0, "おにいちゃんどこいくの？\nえ？", 1, 1, 0, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 1, 1023, 1.5, "北条 綾音", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "これて何か違う…\nあああすみません！", 2, 0, "ふ、不束者ですが\nどうぞ末永く…って、", 1, 1, 0, "わっ…わっ…私、\n天野すずめといいます！", 1, 1025, 1.4, "天野 すずめ", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "離しませんわ………\n絶対に…!!", 2, 0, "あなたは…運命の……\n伴侶……", 1, 1, 0, "……クスクス…私は\n…倉石恵理子……", 1, 1027, 1.4, "倉石 恵理子", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "…そうでしょ？？", 2, 0, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 1, 1, 0, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 1, 1028, 1.4, "佐々木 咲恋", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "あはは、\n私もまだまだだなぁ～", 2, 0, "ぇっと…\nキミ、私のこと知らないの?!", 1, 1, 0, "桜井望だよ！\nよろしくねっ", 1, 1029, 1.4, "桜井 望", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "ショーグン、\nワタシと一緒に天下統一デース！", 2, 0, "初めまして、\n私はニノン・ジュベール申すデス！", 1, 1, 0, "デケデケデンっ！", 1, 1030, 1.4, "ニノン・ジュベール", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "おかしいですね……", 2, 0, "でもって私の隣にいるのが……\nえ、見えない？", 1, 1, 0, "上喜しのぶです。\n手元のドクロが父です。", 1, 1031, 1.4, "上喜 しのぶ", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "そう、\nオラのボケに突っ込める相方が…！", 2, 0, "けんども\nそれには足りないモンが…", 1, 1, 0, "目指すはビッグな\nお笑い芸人だっぺ！", 1, 1033, 1.5, "野戸まひる", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "ちょ\nちょっと一杯飲んできます…！", 2, 0, "ちょっと緊張しちゃって…", 1, 1, 0, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 1, 1034, 1.4, "綾瀬 ゆかり", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "これ以上お話しすることは…\nないです！", 2, 0, "知らない人とは話しちゃいけないので", 1, 1, 0, "氷川鏡華…です", 1, 1036, 1.5, "氷川 鏡華", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 2, 0, "……あ、アラーム。", 1, 1, 0, "柏崎…栞です。", 1, 1038, 1.4, "柏崎 栞", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "野に咲く花が、\n唯一の話相手です。", 2, 0, "私、一人も友達がいなくて……", 1, 1, 0, "ふ、双葉碧です。", 1, 1040, 1.4, "双葉 碧", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "そう思っています。", 2, 0, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 1, 1, 0, "三角千歌です。", 1, 1042, 1.4, "三角 千歌", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "う、疑ってすまなかったな…", 2, 0, "あぁ？\nお前のそいつの仲間か？", 1, 1, 0, "安芸真琴だ。", 1, 1043, 1.4, "安芸 真琴", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 2, 0, "生けとし生ける全ての者よ！", 1, 1, 0, "わらわこそは夜を総べる者！", 1, 1044, 1.4, "イリヤ・オーンスタイン", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "ｌク、クウカに何かご用ですか!?", 2, 0, "ぐふふふふ……はっ！", 1, 1, 0, "そこで騎士は妖精を乱暴に……", 1, 1045, 1.4, "遠見 空花", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "う～ん…\n猫ってホントに最高にゃ～♪", 2, 0, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 1, 1, 0, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 1, 1046, 1.4, "宮坂たまき", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 2, 0, "それでは早速クエストに…", 1, 1, 0, "大神美冬よ！", 1, 1048, 1.4, "大神 美冬", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 2, 0, "クエストもバトルも\n掃除も洗濯も", 1, 1, 0, "星野静流だよ！", 1, 1049, 1.4, "星野静流", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 2, 0, "見ての通りの\nセクシー美少女で", 1, 1, 0, "アタシは玉泉美咲。", 1, 1050, 1.5, "玉泉美咲", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "？？？？", 2, 0, "？？？？", 1, 1, 0, "？？？", 1, 1052, 1.4, "リマ", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "そ、そこまでいうなら\nもらってやる", 2, 0, "菓子でつろうなどと\n稚拙な策を……", 1, 1, 0, "モニカ・ヴァイスヴィントだ。", 1, 1053, 1.5, "モニカ・ヴァイスヴィント", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "そ、そこまでいうなら\nもらってやる", 2, 0, "菓子でつろうなどと\n稚拙な策を……", 1, 1, 0, "モニカ・ヴァイスヴィントだ。", 1, 1058, 1.5, "ペコリーヌ", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "そ、そこまでいうなら\nもらってやる", 2, 0, "菓子でつろうなどと\n稚拙な策を……", 1, 1, 0, "モニカ・ヴァイスヴィントだ。", 1, 1059, 1.5, "コッコロ", 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (0, "そ、そこまでいうなら\nもらってやる", 2, 0, "菓子でつろうなどと\n稚拙な策を……", 1, 1, 0, "モニカ・ヴァイスヴィントだ。", 1, 1060, 1.5, "キャル", 0, 0);
